import{_ as n,C as s,o as e,c as h,j as i,E as t,a as o,a3 as r}from"./chunks/framework.C6R8kWFE.js";const S=JSON.parse(`{"title":"1-dars (Mentor). IoT tushunchasi va qo‘llanish sohalari","description":"","frontmatter":{"title":"1-dars (Mentor). IoT tushunchasi va qo‘llanish sohalari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"week":{"n":1,"link":"/mentor/9-sinf-iot/hafta-01/"},"g":1,"title":"IoT tushunchasi va qo‘llanish sohalari","lead":"IoT tushunchasi va qo‘llanish sohalari","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-1-test.html","student_link":"/9-sinf-iot/hafta-01/dars-1","tabs":[{"g":1,"link":"/mentor/9-sinf-iot/hafta-01/dars-1","current":true},{"g":2,"link":"/mentor/9-sinf-iot/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf-iot/hafta-01/dars-3","current":false}],"prev":null,"next":{"g":2,"title":"IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","link":"/mentor/9-sinf-iot/hafta-01/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-01/dars-1.md","filePath":"mentor/9-sinf-iot/hafta-01/dars-1.md"}`),u={name:"mentor/9-sinf-iot/hafta-01/dars-1.md"},d={class:"blk"},m={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},q={id:"mentor-konspekti",tabindex:"-1"},y={class:"blk"},k={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},v={class:"blk"},c={id:"tezkor-nazorat-savollari",tabindex:"-1"},b={class:"blk"},f={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function T(I,a,p,z,x,_){const l=s("Icon");return e(),h("div",null,[i("div",d,[i("h2",m,[t(l,{name:"file-text"}),a[0]||(a[0]=o(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga Buyumlar Interneti (Internet of Things — IoT) tushunchasi, uning paydo bo&#39;lish tarixi (Kevin Eshton, 1999), an&#39;anaviy internetdan farqli jihatlari hamda IoT texnologiyalarining zamonaviy sohalarda (aqlli uy, sanoat, tibbiyot, qishloq xo&#39;jaligi, transport) qo&#39;llanilishi bo&#39;yicha fundamental bilimlarni berish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar IoT tushunchasini to&#39;g&#39;ri ta&#39;riflay oladi; inson aralashuvisiz qurilmalar o&#39;rtasida ma&#39;lumot almashish (M2M) tamoyilini tushunadi; o&#39;z hayotiy misollarida turli sohalardagi IoT tizimlarini tahlil qila oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>Kirish va qiziqtirish (&quot;Aqlli choynakdan to aqlli shahargacha&quot;): 10 daqiqa</li><li>Yangi mavzu: IoT nima? Tarixi va an&#39;anaviy internetdan farqi: 25 daqiqa</li><li>Qo&#39;llanish sohalari tahlili (Smart Home, IIoT, IoMT, Smart City, Smart Ag): 25 daqiqa</li><li>Amaliy topshiriqlar va muhokama: 15 daqiqa</li><li>Dars xulosasi va tezkor savollar: 5 daqiqa</li></ul></li></ul><hr>",2))]),i("div",g,[i("h2",q,[t(l,{name:"file-text"}),a[3]||(a[3]=o(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-iot-tushunchasi-va-tarixi" tabindex="-1">1. IoT tushunchasi va tarixi <a class="header-anchor" href="#_1-iot-tushunchasi-va-tarixi" aria-label="Permalink to &quot;1. IoT tushunchasi va tarixi&quot;">​</a></h3><ul><li><strong>IoT (Internet of Things — Buyumlar Interneti):</strong> Bu internet orqali o&#39;zaro bog&#39;lanib, inson yordamiga ehtiyoj sezmasdan bir-biriga ma&#39;lumot yubora oladigan, atrof-muhitni sezuvchi va avtomatik qaror qabul qiluvchi jismoniy qurilmalar tarmog&#39;idir.</li><li><strong>Tarixi:</strong> Atama ilk bor 1999 yilda kompyuter olimi <strong>Kevin Eshton (Kevin Ashton)</strong> tomonidan Procter &amp; Gamble kompaniyasida RFID (radiochastotali identifikatsiya) texnologiyalari taqdimotida ishlatilgan.</li><li><strong>An&#39;anaviy internet vs IoT:</strong><ul><li><em>An&#39;anaviy Internet:</em> Odamlar tomonidan kiritilgan ma&#39;lumotlar tarmog&#39;i (Human-to-Human / Human-to-Computer: veb-saytlar, xabarlar, videolar).</li><li><em>IoT Tarmog&#39;i:</em> Qurilmalarning o&#39;zlari to&#39;plagan va almashadigan ma&#39;lumotlar tarmog&#39;i (Machine-to-Machine — M2M).</li></ul></li></ul><h3 id="_2-iot-ning-3-ta-asosiy-xususiyati" tabindex="-1">2. IoT ning 3 ta asosiy xususiyati <a class="header-anchor" href="#_2-iot-ning-3-ta-asosiy-xususiyati" aria-label="Permalink to &quot;2. IoT ning 3 ta asosiy xususiyati&quot;">​</a></h3><ol><li><strong>Atrofni his qilish (Sensing):</strong> Sensorlar orqali harorat, yorug&#39;lik, bosim, gaz, harakat parametrlarini o&#39;lchash.</li><li><strong>Ulanish (Connectivity):</strong> To&#39;plangan ma&#39;lumotlarni simsiz (Wi-Fi, Bluetooth, LoRaWAN, GSM) yoki simli tarmoqlar orqali uzatish.</li><li><strong>Avtonom harakat (Actuation / Automation):</strong> Kelgan buyruq asosida inson buyrug&#39;isiz dvigatelni yoqish, eshikni qulflash, suv quyish yoki signal chalish.</li></ol><h3 id="_3-iot-texnologiyalarining-qo-llanish-sohalari" tabindex="-1">3. IoT texnologiyalarining qo&#39;llanish sohalari <a class="header-anchor" href="#_3-iot-texnologiyalarining-qo-llanish-sohalari" aria-label="Permalink to &quot;3. IoT texnologiyalarining qo&#39;llanish sohalari&quot;">​</a></h3><ol><li><strong>Aqlli Uy (Smart Home):</strong><ul><li>Masofadan boshqariluvchi aqlli chiroqlar, aqlli termostatlar (masalan, Nest), harakat sezgichlari, qochqin gaz va suvni avtomatik to&#39;suvchi klapanlar.</li><li>Maqsad: qulaylik, xavfsizlik va energiyani 30-40% gacha tejash.</li></ul></li><li><strong>Sanoat IoT (IIoT — Industrial IoT):</strong><ul><li>Zavod va fabrikalardagi stanoklar va konveyerlarga vibratsiya va harorat sensorlarini o&#39;rnatish.</li><li><em>Predictive Maintenance (Oldindan ta&#39;mirlash):</em> Stanok buzilmasdan bir necha kun oldin tebranish o&#39;zgarganini sezib, avtomatik xabar beradi.</li></ul></li><li><strong>Tibbiyot IoT (IoMT — Internet of Medical Things):</strong><ul><li>Aqlli puls-oksimetrlar, qondagi glyukoza datchiklari, yurak kardiomonitorlari.</li><li>Bemor uyida yotganda shifokor kompyuterida uning barcha ko&#39;rsatkichlari real vaqtda ko&#39;rinib turadi.</li></ul></li><li><strong>Aqlli Qishloq Xo&#39;jaligi (Smart Agriculture):</strong><ul><li>Tuproq namligi va kislotaliligini o&#39;lchovchi sensorlar, meteorologik stantsiyalar.</li><li>Tuproq qurisa, tomchilatib sug&#39;orish nasosi avtomatik ishga tushadi; yomg&#39;ir yog&#39;sa, o&#39;z-o&#39;zidan to&#39;xtaydi.</li></ul></li><li><strong>Aqlli Shahar va Logistika (Smart City):</strong><ul><li>Aqlli svetoforlar (tirbandlikka qarab yashil chiroq vaqtini o&#39;zgartiradi), aqlli chiqindi qutilari (to&#39;lganida mashinaga xabar beradi), GPS orqali yuk harakatini kuzatish.</li></ul></li></ol><hr>',7))]),i("div",y,[i("h2",k,[t(l,{name:"file-text"}),a[6]||(a[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-oddiy-buyumni-iot-qurilmaga-aylantirish-oson" tabindex="-1">1-topshiriq. Oddiy buyumni IoT qurilmaga aylantirish (oson) <a class="header-anchor" href="#_1-topshiriq-oddiy-buyumni-iot-qurilmaga-aylantirish-oson" aria-label="Permalink to &quot;1-topshiriq. Oddiy buyumni IoT qurilmaga aylantirish (oson)&quot;">​</a></h3><p>Xonada turgan oddiy ko&#39;cha chirog&#39;i (fonar) mavjud. Ushbu chiroqni &quot;Aqlli ko&#39;cha chirog&#39;i&quot;ga (Smart Street Light) aylantirish uchun unga qanday 3 ta komponent qo&#39;shilishi kerak va u qanday avtomatik qoidada ishlashi lozim?</p><p><strong>Yechim:</strong></p><ol><li><strong>Sensor:</strong> LDR (fotorezistor — yorug&#39;lik sensori) va PIR (harakat sensori).</li><li><strong>Boshqaruvchi (Mikrokontroller):</strong> Arduino yoki ESP8266/ESP32 platasi.</li><li><strong>Aktuator:</strong> Rele (Relay) yoki tranzistorli drayver (chiroqni yoqish/o&#39;chirish uchun).</li><li><strong>Ishlash algoritmi:</strong> Kunduzi yorug&#39;lik yuqori bo&#39;lganda chiroq butunlay o&#39;chiq turadi. Tunda yorug&#39;lik tushganda chiroq 20% xira rejimda turadi; agar PIR sensori odam yoki mashina yaqinlashganini sezsa, chiroq 100% yorqinlikka ko&#39;tariladi va odam o&#39;tib ketgach yana xiralashadi. Natijada shahar elektr energiyasi 70% gacha tejaladi.</li></ol><h3 id="_2-topshiriq-issiqxona-uchun-iot-monitoring-tizimi-arxitekturasi-o-rta" tabindex="-1">2-topshiriq. Issiqxona uchun IoT monitoring tizimi arxitekturasi (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-issiqxona-uchun-iot-monitoring-tizimi-arxitekturasi-o-rta" aria-label="Permalink to &quot;2-topshiriq. Issiqxona uchun IoT monitoring tizimi arxitekturasi (o&#39;rta)&quot;">​</a></h3><p>Pomidor yetishtiriladigan zamonaviy issiqxonada hosildorlikni oshirish uchun avtomatlashtirilgan IoT tizimi loyihalanmoqda. Issiqxona ichidagi qaysi 3 ta muhit parametrini doimiy o&#39;lchash kerak va qanday aktuatorlar orqali harorat va namlik barqaror ushlab turiladi?</p><p><strong>Yechim:</strong></p><ol><li><strong>O&#39;lchanadigan parametrlar:</strong><ul><li>Havo harorati va havoning nisbiy namligi (masalan, DHT22 sensori);</li><li>Tuproq namligi (Soil Moisture Sensor);</li><li>Quyosh nuri yoritilganlik darajasi (LDR / Lux sensor).</li></ul></li><li><strong>Ijrochi mexanizmlar (Aktuatorlar):</strong><ul><li>Agar havo harorati 32°C dan oshsa — avtomatik ventilyator yoki darcha ochuvchi servo-motor ishga tushadi;</li><li>Agar tuproq namligi 40% dan pastga tushsa — suv klapani (solenoid valve) ochilib, tomchilatib sug&#39;orish nasosi yoqiladi;</li><li>Agar tuproq me&#39;yoriga yetkazib namlansa — nasos avtomatik o&#39;chadi.</li></ul></li></ol><h3 id="_3-topshiriq-an-anaviy-tizim-vs-iot-logistika-sovuqxonasini-taqqoslash-qiyin" tabindex="-1">3-topshiriq. An&#39;anaviy tizim vs IoT: logistika sovuqxonasini taqqoslash (qiyin) <a class="header-anchor" href="#_3-topshiriq-an-anaviy-tizim-vs-iot-logistika-sovuqxonasini-taqqoslash-qiyin" aria-label="Permalink to &quot;3-topshiriq. An&#39;anaviy tizim vs IoT: logistika sovuqxonasini taqqoslash (qiyin)&quot;">​</a></h3><p>Muzqaymoq va dorilarni tashiydigan refrijerator yuk mashinasi mavjud. An&#39;anaviy usulda yuk tashish bilan IoT tizimi o&#39;rnatilgan refrijerator o&#39;rtasidagi xatolar va xavflarni solishtirib bering. IoT tizimi qanday qilib millionlab dollarlik zararning oldini oladi?</p><p><strong>Yechim:</strong></p><ol><li><strong>An&#39;anaviy tizimda:</strong> Haydovchi yo&#39;lga chiqadi, muzlatgich nosozligi yoki elektr uzilishi faqat manzilga yetib borganda (dorilar erib, yaroqsiz holga kelganda) aniqlanadi. Katta moliyaviy zarar va insonlar salomatligiga xavf yuzaga keladi.</li><li><strong>IoT tizimida:</strong><ul><li>Refrijerator ichiga harorat sensori (DS18B20) va GPS/GSM moduli ulanadi.</li><li>Ma&#39;lumot har 30 soniyada bulutli serverga (Cloud) uzatiladi.</li><li>Agar harorat -18°C dan -10°C gacha ko&#39;tarilsa, tizim bir soniya ichida haydovchining smartfoniga va kompaniya dispetcheriga shoshilinch SMS/Telegram ogohlantirish yuboradi.</li><li>Haydovchi zudlik bilan to&#39;xtab muzlatgichni tekshiradi va mahsulot buzilishining oldi olinadi.</li></ul></li></ol><hr>',13))]),i("div",v,[i("h2",c,[t(l,{name:"file-text"}),a[9]||(a[9]=o(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>&quot;Internet of Things&quot; (IoT) atamasi ilk bor qachon va kim tomonidan taklif qilingan? <ul><li><em>Javob:</em> 1999 yilda kompyuter olimi Kevin Eshton (Kevin Ashton) tomonidan.</li></ul></li><li>An&#39;anaviy internet bilan IoT tarmog&#39;ining asosiy farqi nimada? <ul><li><em>Javob:</em> An&#39;anaviy internetda ma&#39;lumotlarni odamlar kiritadi va ko&#39;radi (Human-to-Human), IoT da esa ma&#39;lumotlarni qurilmalarning o&#39;zlari inson aralashuvisiz to&#39;playdi va almashadi (Machine-to-Machine — M2M).</li></ul></li><li>Tibbiyot sohasida qo&#39;llaniladigan IoT yo&#39;nalishi qisqartmasi qanday ataladi? <ul><li><em>Javob:</em> IoMT (Internet of Medical Things).</li></ul></li><li>IoT tizimida atrof-muhitdagi fizik ko&#39;rsatkichlarni (harorat, yorug&#39;lik, bosim) elektr signaliga aylantiruvchi qism qanday ataladi? <ul><li><em>Javob:</em> Sensor (Datchik).</li></ul></li></ol><hr>",2))]),i("div",b,[i("h2",f,[t(l,{name:"file-text"}),a[12]||(a[12]=o(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,[i("strong",null,"IoT ni oddiy masofadan boshqarish (Remote Control) bilan adashtirish:"),o(" O'quvchilar ko'pincha televizor pultini yoki simsiz o'yinchoq mashinani IoT deb o'ylashadi. IoT bo'lishi uchun qurilma internet/bulut tarmog'iga ulangan bo'lishi, atrof-muhitdan mustaqil ma'lumot to'plashi va tahlil qila olishi shart.")]),i("li",null,[i("strong",null,"Xavfsizlikni unutish:"),o(" IoT qurilmalari internetga to'g'ridan-to'g'ri ulangani sababli, agar standart parollar (masalan, "),i("code",null,"admin/admin"),o(") o'zgartirilmasa, xakerlar aqlli kamera yoki eshik qulflarini osongina buzib kirishi mumkin. Dastlabki darslardanoq xavfsizlik madaniyatini singdirish lozim.")])],-1))])])}const P=n(u,[["render",T]]);export{S as __pageData,P as default};
